 if(!selected)return header+(collections.length?`<div class="lx-music-collections-grid">${collections.map(c=>{const cover=(c.items||[]).map(id=>byId.get(String(id))).find(Boolean);return `<article class="lx-music-collection-card"><button type="button" data-lx-collection-open="${esc(c.id)}">${cover?LX.artwork.markup(cover,{},'lx-music-collection-cover',cover.title):'<span class="lx-music-collection-cover placeholder">♫</span>'}<strong>${esc(c.title)}</strong><small>${c.kind==='album'?'Álbum pessoal':'Playlist'} · ${(c.items||[]).length} músicas</small></button><button type="button" class="lx-music-collection-play" data-lx-collection-play="${esc(c.id)}" aria-label="Reproduzir ${esc(c.title)}">▶</button></article>`}).join('')}</div>`:musicEmpty('Nenhuma coleção ainda','Crie uma playlist ou álbum e adicione músicas pelo botão ＋ em cada capa.'));
