function bookCard(x){const h=D.history()[x.id]||{},p=Math.round(h.progress||0);return `<button class="lx-book-card" onclick="LX.detail(${x.id})"><span class="lx-book-cover" style="background-image:url('${x.cover||''}')"><i>${p>0&&p<100?p+'%':''}</i></span><strong>${esc(x.title)}</strong><small>${esc(x.author||'LX Books')}</small>${p>0&&p<100?`<span class="lx-book-progress"><i style="width:${p}%"></i></span>`:''}</button>`}
function renderBookExperience(){
 const a=items(),h=D.history();$('hero').innerHTML='';
 if(!a.length){$('welcome').innerHTML='';$('homeContent').innerHTML=`<section class="official-empty lx-mode-empty"><span class="eyebrow">LX READER</span><h2>${state.user?.admin?'Sua estante está pronta':'Livros em breve'}</h2><p>${state.user?.admin?'Envie PDF/EPUB ou cadastre capítulos no ADM.':'A biblioteca está sendo preparada.'}</p>${state.user?.admin?'<button class="primary-btn" onclick="LX.openAdmin()">Adicionar livro</button>':''}</section>`;return}
 const cont=a.filter(x=>h[x.id]?.progress>0&&h[x.id]?.progress<100).sort((x,y)=>(h[y.id]?.opened||0)-(h[x.id]?.opened||0)),featured=cont[0]||a.find(x=>x.featured)||a[0],newest=[...a].sort((x,y)=>+new Date(y.publishedAt||y.createdAt||0)-+new Date(x.publishedAt||x.createdAt||0));
 $('welcome').innerHTML=`<header class="lx41-mode-heading"><span class="eyebrow">LX READER</span><h1>Sua biblioteca.</h1><p>${a.length} livros para ler no seu ritmo.</p></header>`;
 if(state.query||state.category!=='Início'){$('homeContent').innerHTML=`<section class="lx-books-section"><div class="lx-section-title"><div><span class="eyebrow">ESTANTE</span><h2>${state.query?`Resultados para “${esc(state.query)}”`:esc(state.category)}</h2></div><span>${a.length} livros</span></div><div class="lx-books-grid">${a.map(bookCard).join('')}</div></section>`;return}
 let html='';if(cont.length)html+=`<section class="lx-books-section"><div class="lx-section-title"><div><span class="eyebrow">CONTINUE</span><h2>Continuar lendo</h2></div></div><div class="lx-books-grid continue">${cont.slice(0,8).map(bookCard).join('')}</div></section>`;
 html+=`<section class="lx-books-section"><div class="lx-section-title"><div><span class="eyebrow">BIBLIOTECA</span><h2>Descubra sua próxima leitura</h2></div></div><div class="lx-books-grid">${newest.slice(0,14).map(bookCard).join('')}</div></section>`;
 const genres=[...new Set(a.map(x=>x.genre).filter(Boolean))].slice(0,4);genres.forEach(g=>{const group=a.filter(x=>x.genre===g);html+=`<section class="lx-books-section"><div class="lx-section-title"><div><h2>${esc(g)}</h2></div></div><div class="lx-books-grid compact">${group.slice(0,8).map(bookCard).join('')}</div></section>`});$('homeContent').innerHTML=html;
}

function cinemaSection(title,subtitle,list,{category='',limit=0,id=''}={}){
 if(!list.length)return '';
 const shown=limit?list.slice(0,limit):list;
 return `<section class="lx-cinema-section" ${id?`data-cinema-section="${id}"`:''}><header class="lx-cinema-heading"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div>${category&&shown.length<list.length?`<button type="button" data-cinema-category="${esc(category)}">Ver todos · ${list.length}</button>`:`<small>${list.length} títulos</small>`}</header><div class="lx-cinema-grid">${shown.map(x=>card({...x,banner:x.cover||x.banner})).join('')}</div></section>`;
}
function cinemaArchive(title,subtitle,list,id){return list.length?`<details class="lx-cinema-archive" data-cinema-section="${id}"><summary>${esc(title)} · ${list.length} títulos</summary>${cinemaSection(title,subtitle,list)}</details>`:''}
function renderVideoCatalog(a,filmTabs){
 const group=LX.cinemaCatalog.groups(a),home=state.category==='Início';
 const h=D.history(),continuing=a.filter(x=>h[x.id]?.progress>0&&h[x.id]?.progress<98&&LX.cinemaCatalog.playable(x));
 let html=filmTabs;
 if(home&&continuing.length)html+=rail('Continuar assistindo','Retome suas histórias de onde parou.',continuing,true);
 html+=`<section class="lx-cinema-intro"><span class="eyebrow">LX CINEMA</span><h2>${home?'Sua próxima sessão começa aqui':esc(state.category)}</h2><p>${home?'Filmes, doramas, séries e animes em seu próprio espaço. Escolha uma capa e descubra sua próxima história.':state.category==='Filmes'?'Longas completos primeiro. Curtas e acervo histórico ficam em suas próprias coleções.':'Capas e temporadas organizadas para você encontrar sua próxima história.'}</p></section>`;
 if(home||state.category==='Filmes'){
  html+=cinemaSection('Filmes recentes · completos','Longas a partir de 2020, com duração e fonte oficial.',group.recent,{category:'Filmes',limit:home?12:0,id:'recent-films'});
  html+=cinemaSection('Mais filmes para assistir','Longas com reprodução disponível na LX Plus.',group.films,{category:'Filmes',limit:home?12:0,id:'films'});
  if(!home)html+=cinemaSection('Catálogo de filmes','Escolha um filme disponível no player LX.',group.catalog,{id:'film-catalog'});
 }
 if(home||state.category==='Doramas')html+=cinemaSection('Doramas','Romance, drama e novas histórias. Cada título reúne seus episódios.',group.doramas,{category:'Doramas',limit:home?12:0,id:'doramas'});
 if(home||state.category==='Séries')html+=cinemaSection('Séries','Temporadas e episódios organizados por título.',group.series,{category:'Séries',limit:home?12:0,id:'series'});
 if(home||state.category==='Animes')html+=cinemaSection('Animes','Suas animações e aventuras, em uma coleção separada.',group.anime,{category:'Animes',limit:home?12:0,id:'anime'});
 if(home&&group.catalog.length)html+=cinemaSection('Explore o catálogo de filmes','Fichas e capas para descobrir. “Em breve” indica títulos sem reprodução cadastrada.',group.catalog,{category:'Filmes',limit:12,id:'film-catalog'});
 if(!home&&state.category==='Filmes'){
  html+=cinemaArchive('Curtas e animações','Histórias curtas do Blender Studio e outras produções.',group.shorts,'shorts');
  html+=cinemaArchive('Acervo histórico','Clássicos e documentários históricos.',group.historical,'historical');
 }
 $('homeContent').innerHTML=html;
}
