function renderHome(){if(state.query&&LX.universal?.renderSearch)return LX.universal.renderSearch(state.query);if(state.mode==='Ouvir')return renderMusicExperience();const a=items(),filmTabs=renderFilmTabs();if(state.mode==='Assistir'&&['Início','Filmes','Doramas','Séries','Animes'].includes(state.category)&&!state.query)return renderVideoCatalog(a,filmTabs);if(state.category==='Cinema livre'){$('homeContent').innerHTML=filmTabs+(a.length?`<section class="lx-open-film-intro"><span class="eyebrow">CINEMA LIVRE</span><h2>Escolha e dê o play</h2><p>Filmes e curtas com licença aberta. Reprodução direta no player LX Plus.</p><small>${a.length} títulos disponíveis</small></section>`+rail('Blender Studio','Animações e ficção para descobrir.',a.filter(x=>!!x.openFilmEvidence?.producerPage))+rail('Acervo histórico','Curtas e documentários do Prelinger Archives.',a.filter(x=>!x.openFilmEvidence?.producerPage)):'<section class="official-empty"><h2>Novos filmes em breve</h2></section>');return}if(state.category==='Parceria com Plex'){$('homeContent').innerHTML=filmTabs+(a.length?rail('Parceria com Plex','Filmes do catálogo Plex. A reprodução fica disponível quando uma fonte de vídeo é cadastrada.',a):'<section class="official-empty"><span class="eyebrow">LX PLUS</span><h2>Disponível em breve</h2><p>Os filmes desta aba aparecerão aqui conforme o catálogo for atualizado.</p></section>');return}if(!a.length){$('homeContent').innerHTML=filmTabs+`<section class="official-empty"><span class="eyebrow">LX PLUS</span><h2>${state.user?.admin?'Catálogo pronto para você organizar':'Novidades em breve'}</h2><p>${state.user?.admin?'A plataforma está limpa. Use o Painel ADM para cadastrar seus conteúdos, capas, banners e lançamentos.':'O catálogo está sendo preparado.'}</p>${state.user?.admin?'<button class="primary-btn" onclick="LX.openAdmin()">Abrir Painel ADM</button>':''}</section>`;return}if(state.query){$('homeContent').innerHTML=rail(`Resultados para “${esc(state.query)}”`,'Busca tolerante a erros por título, elenco, autor, artista, gênero e tags.',a);return}if(state.category!=='Início'){$('homeContent').innerHTML=filmTabs+rail(state.category,'Tudo nesta categoria.',a);return}const h=D.history(),pref=D.preferences()[state.user?.email||'']||{},histEntries=Object.entries(h).filter(([,v])=>v?.opened).sort((a,b)=>(b[1].opened||0)-(a[1].opened||0)),recentId=histEntries[0]?.[0],recent=D.catalog().find(x=>String(x.id)===String(recentId)),cont=a.filter(x=>h[x.id]?.progress>0&&h[x.id]?.progress<98),recs=D.recommendation(a,h,D.ratings(),pref).slice(0,12),because=recent?a.filter(x=>x.id!==recent.id&&(x.genre===recent.genre||x.type===recent.type)&&!h[x.id]).slice(0,10):[],top=[...a].sort((x,y)=>(y.trending?1:0)-(x.trending?1:0)||(+y.priority||0)-(+x.priority||0)).slice(0,10),newest=[...a].sort((x,y)=>(+new Date(y.publishedAt||y.createdAt||0))-(+new Date(x.publishedAt||x.createdAt||0))).slice(0,12);let html='';if(cont.length)html+=rail(state.mode==='Ler'?'Continuar lendo':state.mode==='Ouvir'?'Ouvir novamente':'Continuar assistindo','Retome exatamente do segundo em que parou.',cont,true);if(recs.length){const why=pref.genres?.length?`Preferências: ${pref.genres.slice(0,3).join(', ')}. Também usamos histórico, notas e tags.`:'Baseado no seu histórico, avaliações, gêneros e tags. Você pode ajustar isso no Perfil.';html+=rail('Recomendado para você',why,recs)}if(because.length)html+=rail(`Porque você ${recent.type==='Livro'?'leu':recent.type==='Música'?'ouviu':'assistiu'} ${esc(recent.title)}`,'Uma seleção relacionada ao seu histórico recente.',because);html+=rail('Top 10 LX','Os títulos mais fortes neste momento.',top,false,true);html+=rail('Em alta','O que está chamando atenção.',a.filter(x=>x.trending));html+=rail('Lançados recentemente','As novidades mais recentes da plataforma.',newest);[...new Set(a.map(x=>x.genre).filter(g=>typeof g==='string'&&g.trim()))].slice(0,5).forEach(g=>html+=rail(esc(g),`Seleção em ${esc(g.toLowerCase())}.`,a.filter(x=>x.genre===g)));$('homeContent').innerHTML=html}
function renderApp(){if(state.query&&LX.universal?.renderSearch)return LX.universal.renderSearch(state.query);$('app')?.classList.toggle('lx-music-mode',state.mode==='Ouvir');renderCategories();$('welcome')?.classList.toggle('hidden',state.mode==='Ao vivo');LX.syncMobileNavState?.();if(state.mode==='Ao vivo')LX.contentHub?.renderLive?.();else if(state.mode==='Assistir'&&state.category==='Catálogo Online')LX.contentHub?.renderWatch?.();else if(state.mode==='Ler'&&state.category==='Biblioteca Pública')LX.contentHub?.renderBooks?.();else if(state.mode==='Ouvir')renderMusicExperience();else if(state.mode==='Ler')renderBookExperience();else{renderHero();renderWelcome();renderHome()}updateNoticeCount();try{LX.syncPremiumShell?.()}catch(e){console.warn('LX premium shell sync',e)}const adm=$('adminTopBtn');if(adm)adm.classList.toggle('hidden',!state.user?.admin);LX.universal?.onRender?.()}
function scroll(id,d){const e=$(id);e?.scrollBy({left:d*e.clientWidth*.82,behavior:'smooth'})}
function close(){$('overlay').classList.add('hidden')}function closePlayer(){if(LX.stopMiniPlayer)LX.stopMiniPlayer(true);else{$('playerOverlay').classList.add('hidden');$('videoEl')?.pause()}}function closeReader(){const reader=LX.readerRuntime;if(reader){reader.request++;reader.cleanup?.();reader.cleanup=null}$('readerOverlay').classList.add('hidden');$('readerModal').replaceChildren()}
function updateNoticeCount(){const system=D.notices().filter(x=>!x.read).length,chat=Number(LX.chat?.unreadTotal?.()||0),cloud=Number(LX.chat?.cloudUnread?.()||0),community=Math.max(chat,cloud),c=system+community;const el=$('notifyCount');if(el){el.textContent=c>99?'99+':String(c);el.style.display=c?'grid':'none'}try{if('setAppBadge'in navigator)c?navigator.setAppBadge(c):navigator.clearAppBadge?.()}catch{}}
LX.ui={$, $$, state, esc, show, toast, initials, posterWalls, authTab, renderProfiles, renderApp, renderHome, renderCategories, items, close, closePlayer, closeReader, scroll, updateNoticeCount};
